  "b2.farules": "ڊيپريسيئيشن ڪيئن ڪڍيو وڃي ٿو",
  "b2.farule1": "کاتن جو ڊيپريسيئيشن ڪمپنيز ايڪٽ، 2013 جي شيڊيول II موجب آهي: هر قسم جي ايسيٽ جي ڪارآمد عمر آهي (جيئن ڪمپيوٽر 3 سال، فرنيچر 10 سال، پلانٽ ۽ مشينري 15 سال، ڪار 8 سال)، بچيل ويليو عام طور قيمت جي 5% کان وڌيڪ نه ٿيندي، ۽ سال جي وچ ۾ شامل يا وڪيل ايسيٽ تي صرف استعمال وارن ڏينهن جو ڊيپريسيئيشن لڳي ٿو. اسٽريٽ لائين (SLM: هر سال برابر رقم) يا رٽن ڊائون ويليو (WDV: بچيل رقم تي مقرر ريٽ) چونڊيو. پروپرائيٽر ۽ فرمون گهڻو ڪري اهو ئي طريقو اپنائين ٿيون؛ فيصلو توهان جو اڪائونٽنٽ ڪري ٿو.",
  "b2.farule2": "انڪم ٽيڪس ڊيپريسيئيشن هر بلاڪ جو الڳ ڪڍيو وڃي ٿو: بلاڪ ريٽ تي رٽن ڊائون ويليو (جيئن پلانٽ ۽ مشينري 15%، فرنيچر 10%، ڪمپيوٽر 40%)، سال ۾ 180 ڏينهن کان گهٽ استعمال ٿيل ايسيٽ تي اڌ ريٽ، ۽ وڪري جا پئسا بلاڪ مان گهٽجن ٿا. هي صرف انڪم ٽيڪس ريٽرن لاءِ آهي، کاتن ۾ ڪڏهن به نه وجهبو آهي. ڀريل ريٽ عام بلاڪ ريٽ آهن: پنهنجي اڪائونٽنٽ سان پڪ ڪريو، خاص ڪري 1 اپريل 2026 کان انڪم ٽيڪس ايڪٽ، 2025 هيٺ سالن لاءِ.",
  "b2.farule3": "ڊيپريسيئيشن توهان جي کاتن ۾ تڏهن ئي وڃي ٿو جڏهن توهان 'ڊيپريسيئيشن وجهو' دٻايو: سال جي آخري ڏينهن (يا سال جي وچ ۾ اڄ) جي جرنل انٽري ڊيپريسيئيشن کي ڊيبٽ ڪري ٿي ۽ هر ايسيٽ گهٽائي ٿي. بعد ۾ ايسيٽ بدلايو ته ٻيهر وجهو، صرف فرق شامل ٿيندو.",
